WITH scored AS (SELECT id, store_id, product_id, sale_date, units, revenue, DENSE_RANK() OVER (ORDER BY revenue) revenue_dense_rank, ROUND(revenue / SUM(revenue) OVER (PARTITION BY store_id), 4) revenue_share, LAST_VALUE(units, TRUE) OVER (PARTITION BY store_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_units FROM store_sales) SELECT store_id, product_id, COUNT(*) AS cnt, COUNT(DISTINCT store_id) AS distinct_store_ids, COUNT(DISTINCT product_id) AS distinct_product_ids FROM scored GROUP BY 1, 2 ORDER BY distinct_product_ids DESC
